import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageStudents() {
  const [students, setStudents] = useState([]);

  useEffect(() => {
    axios.get('http://localhost:8081/api/view-students')
      .then(res => setStudents(res.data))
      .catch(err => console.error(err));
  }, []);

  return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif' }}>
      <h2 style={{ color: '#1e293b', marginBottom: '20px' }}>Manage Students</h2>
      
      <div style={{ backgroundColor: 'white', borderRadius: '8px', boxShadow: '0 2px 10px rgba(0,0,0,0.05)', overflow: 'hidden' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
            <tr>
              <th style={{ padding: '15px', color: '#475569' }}>Name</th>
              <th style={{ padding: '15px', color: '#475569' }}>Grade</th>
              <th style={{ padding: '15px', color: '#475569' }}>Subjects</th>
              <th style={{ padding: '15px', color: '#475569' }}>Phone Number</th>
            </tr>
          </thead>
          <tbody>
            {students.length > 0 ? students.map((student) => (
              <tr key={student.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                <td style={{ padding: '15px', fontWeight: 'bold' }}>{student.name}</td>
                <td style={{ padding: '15px' }}>{student.grade}</td>
                <td style={{ padding: '15px' }}>{student.subjects}</td>
                <td style={{ padding: '15px' }}>{student.phone_number}</td>
              </tr>
            )) : (
              <tr><td colSpan="4" style={{ padding: '20px', textAlign: 'center', color: '#ef4444' }}>No students found in Database.</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}
